import{useState,useEffect,useRef,useCallback}from"react";

// -- Backend API URL - update after Railway deployment --
const API_BASE = "https://dorra-backend-3.onrender.com";

async function apiPost(path, body) {
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 45000);
    const res = await fetch(API_BASE + path, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
    clearTimeout(timeout);
    return await res.json();
  } catch(e) {
    console.error("API error:", e);
    return { error: e.message };
  }
}

async function apiGet(path, adminSecret) {
  try {
    const headers = adminSecret ? { "x-admin-secret": adminSecret } : {};
    const res = await fetch(API_BASE + path, { headers });
    return await res.json();
  } catch(e) {
    console.error("API error:", e);
    return [];
  }
}

async function apiPatch(path, body, adminSecret) {
  try {
    const res = await fetch(API_BASE + path, {
      method: "PATCH",
      headers: { "Content-Type": "application/json", "x-admin-secret": adminSecret || "" },
      body: JSON.stringify(body),
    });
    return await res.json();
  } catch(e) {
    return { error: e.message };
  }
}

